frappe.ui.form.on('Stock Entry', {
    refresh: function(frm) {
        // Call the function to update expense accounts for each row in the table
        frm.doc.items.forEach(row => {
            updateExpenseAccount(frm, row.doctype, row.name);
        });
    }
});

function updateExpenseAccount(frm, cdt, cdn) {
    let row = frappe.get_doc(cdt, cdn);
    let default_account = '';

    if (frm.doc.stock_entry_type === 'Manufacture') {
        default_account = 'Finished Goods - YC';
    } else if (frm.doc.stock_entry_type === 'Material Consumption for Manufacture') {
        default_account = 'Work In Progress - YC';
    }
    if (default_account) {
        frappe.model.set_value(cdt, cdn, 'expense_account', default_account);
    }
}

frappe.ui.form.on('FUEL And LUBRICANT REQUEST FORM', {
	refresh(frm) {
		// your code here
	},
	previous_kmrhr:function(frm){
	    calculateKmDiff(frm);

	},
	current_kmrhr:function(frm){
	    calculateKmDiff(frm);
	},
	next_kmrhr:function(frm){
	    calculateActual(frm);

	}
	,
	previously_filled_fuel:function(frm){
	    calculateActual(frm);


	}
})
function calculateKmDiff(frm){
    let prev=frm.doc.previous_kmrhr;
    let now =frm.doc.current_kmrhr;

    if (prev && now) {
        let actual=now-prev;
        frm.set_value('next_kmrhr', actual);

    }
}

function calculateActual(frm){
    let previousFilled = frm.doc.previously_filled_fuel;
    let kmDiff = frm.doc.next_kmrhr;

    if (previousFilled && kmDiff){
        let actual=  kmDiff / previousFilled ;
        frm.set_value('actual', actual);

    }
}

frappe.ui.form.on('Employee Surveillance', {
    joining_date: function(frm, cdt, cdn) {
        calculate_date_difference(frm, cdt, cdn);
    },
    record_date: function(frm, cdt, cdn) {
        calculate_date_difference(frm, cdt, cdn);
    },
    basic_salary: function(frm, cdt, cdn) {
        calculate_severance(frm, cdt, cdn);
    }
});

function calculate_date_difference(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    let joining_date = row.joining_date ? new Date(row.joining_date) : null;
    let record_date = row.record_date ? new Date(row.record_date) : null;

    if (joining_date && record_date) {
        let diffInMs = record_date - joining_date;
        let totalDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));

        let years = Math.floor(totalDays / 365.25);
        let remainingDaysAfterYears = totalDays % 365.25;
        let months = Math.floor(remainingDaysAfterYears / 30.44);
        let days = Math.floor(remainingDaysAfterYears % 30.44);

        frappe.model.set_value(cdt, cdn, 'total_year', years);
        frappe.model.set_value(cdt, cdn, 'total_month', months);
        frappe.model.set_value(cdt, cdn, 'total_date', days);
    } else {
        frappe.model.set_value(cdt, cdn, 'total_year', 0);
        frappe.model.set_value(cdt, cdn, 'total_month', 0);
        frappe.model.set_value(cdt, cdn, 'total_date', 0);
    }
}

function calculate_severance(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    let total_year = row.total_year || 0;
    let total_month = row.total_month || 0;
    let total_date = row.total_date || 0;
    let basic_salary = row.basic_salary || 0;

    let result = basic_salary + (total_year - 1) * (basic_salary / 3) + 
                 (basic_salary / 3 / 12 * total_month) + 
                 (basic_salary / 3 / 365 * total_date);

    frappe.model.set_value(cdt, cdn, 'severance_amount_in_birr', result);
}

frappe.ui.form.on('Employee annual leave amount', {
    unused_annual_leave_balance: function(frm, cdt, cdn) {
        calculate_total(frm, cdt, cdn);
    },
    basic_salary: function(frm, cdt, cdn) {
        calculate_total(frm, cdt, cdn);
    },
});

function calculate_total(frm, cdt, cdn) {
    let doc = locals[cdt][cdn];
    let unused_annual_leave_balance= doc.unused_annual_leave_balance || 0;
    let basic_salary= doc.basic_salary|| 0;

    console.log("Unused annual leave balance:", unused_annual_leave_balance);
    console.log("Basic salary:", basic_salary);

    // Formula for severance calculation
    let result = unused_annual_leave_balance*basic_salary/26;
   frappe.model.set_value(cdt, cdn, 'annual_leave_amount_in_birr', result);
}


frappe.ui.form.on('Employee annual leave amount', {
    to_date: function (frm) {
        if (frm.doc.from_date) {
            console.log("I am calling this now")
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Leave Ledger Entry",
                    filters: {
                        employee: frm.doc.employee, // Match the employee
                        leave_type: "Annual Leave", // Change this if necessary
                        is_expired: 0, // Only include non-expired leaves
                        to_date: [">=", frm.doc.from_date], // Ensure the leave ends after `from_date`
                        from_date: ["<=", frm.doc.to_date] // Ensure the leave starts before `to_date`
                    },
                    fields: ["*"] // Only fetch the `leaves` field
                },
                callback: function (r) {
                    console.log("the origiginal message is ",r)
                    if (r.message) {
                        console.log("the message for the leave is ",r.message)
                        // Calculate the total unused leaves
                        const totalUnusedLeaves = r.message.reduce((total, entry) => total + (entry.leaves || 0), 0);
                        console.log("total unused leave is ",totalUnusedLeaves)

                        // Set the value in the field
                        frm.set_value("unused_annual_leave_balance", totalUnusedLeaves);
                        frm.refresh_field('unused_annual_leave_balance');
                    }
                }
            });
        }
    }
});
